query PaymentsListCharges {
  discover {
    payments {
      listCharges {
        charges {
          receipt
          amountCents
          items
          chargedAt
        }
      }
    }
  }
}

query StateMachineListMachines {
  discover {
    stateMachine {
      listMachines {
        machines {
          name
          hasEffect
        }
      }
    }
  }
}
